def cdrom_audio_play_track_2_vectors() -> list[dict[str, object]]:
    entry = 0x13C4
    expected_hash = "b5dc8b1767297a8a0800d4247522ddafeb89e72e56f9186c7c81d473e3f121fb"
    if hashlib.sha256(EXE[entry : entry + 187]).hexdigest() != expected_hash:
        raise AssertionError("0x13c4: recovered 187-byte body changed")

    def frame_from_msf(position: int) -> int:
        return (
            ((position >> 16) & 0xFF) * 4500
            + ((position >> 8) & 0xFF) * 75
            + (position & 0xFF)
            - 150
        ) & 0xFFFFFFFF

    game_segment = 0x3000
    data_segment = 0x1800
    cases = (
        ("disabled", 0x00, 0x03, 0x00000200, 0x00010000),
        ("ordinary_track", 0x01, 0x03, 0x00120320, 0x003A1025),
        ("high_byte_ignored", 0x81, 0x17, 0xA5120320, 0x5A3A1025),
        ("pregap_underflow", 0xFF, 0x00, 0x00000000, 0x00000200),
        ("end_before_start", 0x01, 0xFE, 0x00300020, 0x00100010),
        ("maximum_components", 0x01, 0xFF, 0xFFFFFFFF, 0x00FFFFFF),
    )
    vectors = []

    for case_index, (name, present, drive, start_position, end_position) in enumerate(cases):
        request_before = bytes(
            (0x23 + case_index * 0x1F + index * 0x11) & 0xFF
            for index in range(22)
        )
        decoy_before = bytes(
            (0xB1 + case_index * 0x0B + index * 3) & 0xFF
            for index in range(22)
        )
        track_before = bytearray(
            (0x69 + case_index * 7 + index * 5) & 0xFF for index in range(7)
        )
        disc_before = bytearray(
            (0x91 + case_index * 9 + index * 3) & 0xFF for index in range(7)
        )
        track_before[2:6] = struct.pack("<I", start_position)
        disc_before[3:7] = struct.pack("<I", end_position)
        initial = {
            "eax": 0xA5A51234 + case_index,
            "ebx": 0xB6B62468 + case_index,
            "ecx": 0xC7C7369C + case_index,
            "edx": 0xD8D855AA + case_index,
            "esi": 0xE9E96789 + case_index,
            "edi": 0xFAFA789A + case_index,
            "ebp": 0x1B1B1357 + case_index,
            "ds": data_segment,
            "es": 0x2400,
            "fs": 0x2800,
            "gs": game_segment,
            "flags": 0x0293,
        }
        interrupts: list[dict[str, object]] = []
        interrupt_flags = 0x0845

        def interrupt(machine: Uc, number: int) -> None:
            interrupts.append(
                {
                    "number": number,
                    "eax": machine.reg_read(UC_X86_REG_EAX),
                    "ebx": machine.reg_read(UC_X86_REG_EBX),
                    "ecx": machine.reg_read(UC_X86_REG_ECX),
                    "edx": machine.reg_read(UC_X86_REG_EDX),
                    "ds": machine.reg_read(UC_X86_REG_DS),
                    "es": machine.reg_read(UC_X86_REG_ES),
                    "request": bytes(
                        machine.mem_read(game_segment * 16 + 0x0B72, 22)
                    ).hex(),
                }
            )
            machine.reg_write(UC_X86_REG_EAX, 0xDEADBEEF)
            machine.reg_write(UC_X86_REG_EDX, 0xC001D00D)
            machine.reg_write(UC_X86_REG_EFLAGS, interrupt_flags)

        machine = execute(
            entry,
            0x147E,
            initial,
            [
                (game_segment, 0x01B9, bytes([drive])),
                (game_segment, 0x0AE6, bytes([present])),
                (game_segment, 0x0B5B, bytes(disc_before)),
                (game_segment, 0x0B6B, bytes(track_before)),
                (game_segment, 0x0B72, request_before),
                (data_segment, 0x01B9, bytes([drive ^ 0xA5])),
                (data_segment, 0x0AE6, bytes([present ^ 0x5A])),
                (data_segment, 0x0B72, decoy_before),
            ],
            interrupt_handler=interrupt,
        )

        enabled = (present & 1) != 0
        start_frame = frame_from_msf(start_position)
        end_frame = frame_from_msf(end_position)
        duration = (end_frame - start_frame) & 0xFFFFFFFF
        expected_request = bytearray(request_before)
        expected_interrupts: list[dict[str, object]] = []
        if enabled:
            expected_request[0] = 0x16
            expected_request[2] = 0x84
            expected_request[0x0E:0x12] = struct.pack("<I", start_position)
            expected_request[0x12:0x16] = struct.pack("<I", duration)
            expected_interrupts.append(
                {
                    "number": 0x2F,
                    "eax": 0x00001510,
                    "ebx": (initial["ebx"] & 0xFFFF0000) | 0x0B72,
                    "ecx": (initial["ecx"] & 0xFFFF0000) | drive,
                    "edx": 0,
                    "ds": game_segment,
                    "es": game_segment,
                    "request": bytes(expected_request).hex(),
                }
            )
        if interrupts != expected_interrupts:
            raise AssertionError(f"0x13c4 {name}: interrupts={interrupts!r}")
        if bytes(machine.mem_read(game_segment * 16 + 0x0B72, 22)) != bytes(
            expected_request
        ):
            raise AssertionError(f"0x13c4 {name}: final request mismatch")
        if bytes(machine.mem_read(game_segment * 16 + 0x0B5B, 7)) != bytes(disc_before):
            raise AssertionError(f"0x13c4 {name}: changed disc info")
        if bytes(machine.mem_read(game_segment * 16 + 0x0B6B, 7)) != bytes(track_before):
            raise AssertionError(f"0x13c4 {name}: changed track info")
        if bytes(machine.mem_read(data_segment * 16 + 0x0B72, 22)) != decoy_before:
            raise AssertionError(f"0x13c4 {name}: changed DS decoy")
        for register in (
            "eax", "ebx", "ecx", "edx", "esi", "edi", "ebp",
            "ds", "es", "fs", "gs",
        ):
            if machine.reg_read(REGISTERS[register]) != initial[register]:
                raise AssertionError(f"0x13c4 {name}: changed {register}")

        final_flags = machine.reg_read(UC_X86_REG_EFLAGS)
        flag_mask = 0x08D5 if enabled else 0x08C5
        expected_flags = interrupt_flags if enabled else 0x0044
        if final_flags & flag_mask != expected_flags & flag_mask:
            raise AssertionError(
                f"0x13c4 {name}: flags={final_flags:#x}, expected={expected_flags:#x}"
            )
        vectors.append(
            {
                "name": name,
                "cdrom_present": present,
                "drive": drive,
                "start_position": f"0x{start_position:08x}",
                "end_position": f"0x{end_position:08x}",
                "start_frame": start_frame,
                "end_frame": end_frame,
                "duration": duration,
                "interrupts": interrupts,
                "final_request": bytes(expected_request).hex(),
                "defined_flags": final_flags & flag_mask,
            }
        )
    return vectors


def keyboard_read_vectors() -> list[dict[str, object]]:
    cases = [
        ("empty", False, 0x0000),
        ("ascii", True, 0x1E61),
        ("extended", True, 0x4800),
        ("high", True, 0xFFFF),
    ]
    vectors = []
    for name, available, key_code in cases:
        interrupts = []
        initial = {
            "eax": 0xA5A51234,
            "bx": 0x2468,
            "cx": 0x369C,
            "dx": 0x55AA,
            "si": 0x6789,
            "di": 0x789A,
            "bp": 0x1357,
            "ds": 0x2000,
            "es": 0x2400,
            "gs": 0x2800,
        }

        def interrupt(machine: Uc, number: int) -> None:
            ax = machine.reg_read(UC_X86_REG_AX)
            interrupts.append((number, ax))
            if len(interrupts) == 1:
                if (number, ax) != (0x16, 0x0100):
                    raise AssertionError(f"0x267D {name}: bad keyboard poll")
                flags = machine.reg_read(UC_X86_REG_EFLAGS)
                if available:
                    machine.reg_write(UC_X86_REG_EFLAGS, flags & ~0x40)
                    machine.reg_write(UC_X86_REG_AX, key_code)
                else:
                    machine.reg_write(UC_X86_REG_EFLAGS, flags | 0x40)
                    machine.reg_write(UC_X86_REG_AX, 0xBEEF)
                return
            if (number, ax) != (0x16, 0x0000):
                raise AssertionError(f"0x267D {name}: bad keyboard read")
            machine.reg_write(UC_X86_REG_AX, key_code)

        machine = execute(
            0x267D,
            0x268C,
            initial,
            [],
            interrupt_handler=interrupt,
        )
        expected_interrupts = 2 if available else 1
        if len(interrupts) != expected_interrupts:
            raise AssertionError(f"0x267D {name}: interrupts={interrupts!r}")
        expected_ax = key_code if available else 0
        if machine.reg_read(UC_X86_REG_AX) != expected_ax:
            raise AssertionError(f"0x267D {name}: returned the wrong key code")
        for register in ("bx", "cx", "dx", "si", "di", "bp", "ds", "es", "gs"):
            if machine.reg_read(REGISTERS[register]) != initial[register]:
                raise AssertionError(f"0x267D did not preserve {register}")

        vectors.append(
            {
                "name": name,
                "available": available,
                "key_code": key_code,
                "interrupts": [list(item) for item in interrupts],
                "result_ax": machine.reg_read(UC_X86_REG_AX),
            }
        )
    return vectors


def print_string_dos_vectors() -> list[dict[str, object]]:
    data_segment = 0x2000
    cases = [
        (0x0100, b""),
        (0x0100, b"A"),
        (0x1357, b"DOS$TEXT"),
        (0xFFFC, bytes([0x80, 0xFE, 0x24, 0x7F])),
    ]
    vectors = []
    for source_offset, payload in cases:
        source = bytearray(0x10000)
        for index, value in enumerate(payload + b"\0"):
            source[(source_offset + index) & 0xFFFF] = value
        interrupts = []
        initial = {
            "eax": 0xA5A51234,
            "bx": 0x2468,
            "cx": 0x369C,
            "dx": 0x55AA,
            "si": source_offset,
            "di": 0x789A,
            "bp": 0x1357,
            "ds": data_segment,
            "es": 0x2400,
            "gs": 0x2800,
        }

        def interrupt(machine: Uc, number: int) -> None:
            ax = machine.reg_read(UC_X86_REG_AX)
            dx = machine.reg_read(UC_X86_REG_DX)
            interrupts.append((number, ax, dx))
            if number != 0x21 or (ax >> 8) != 2:
                raise AssertionError("0x0D61 invoked the wrong DOS service")
            machine.reg_write(UC_X86_REG_AX, (ax & 0xFF00) | (dx & 0xFF))

        machine = execute(
            0x0D61,
            0x0D74,
            initial,
            [(data_segment, 0, bytes(source))],
            interrupt_handler=interrupt,
        )
        actual_payload = bytes(dx & 0xFF for _number, _ax, dx in interrupts)
        if actual_payload != payload:
            raise AssertionError(
                f"0x0D61 si={source_offset:#x}: output={actual_payload!r}"
            )
        for register in ("eax", "bx", "cx", "dx", "si", "di", "bp", "ds", "es", "gs"):
            if machine.reg_read(REGISTERS[register]) != initial[register]:
                raise AssertionError(f"0x0D61 did not preserve {register}")

        vectors.append(
            {
                "source_offset": source_offset,
                "payload": list(payload),
                "dos_calls": len(interrupts),
                "call_dx": [dx for _number, _ax, dx in interrupts],
                "preserved_eax": machine.reg_read(UC_X86_REG_EAX),
            }
        )
    return vectors


def error_overlay_draw_vectors() -> list[dict[str, object]]:
    entry = 0x0D75
    return_address = 0xFD75
    expected_hash = "a03c615631c6c929440cfafa741891a1b0bdb4dc0b4b8a1c6b15607ec3f9e3a4"
    if hashlib.sha256(EXE[entry : entry + 237]).hexdigest() != expected_hash:
        raise AssertionError("0x0d75: recovered 237-byte body changed")

    cases = (
        {"name": "coding_error", "mode": 0},
        {"name": "file_error", "mode": 1, "detail": b"blood.dat"},
        {
            "name": "allocation_error_positive",
            "mode": 2,
            "handle": 0x1234,
            "free_bytes": 0x12345678,
        },
        {
            "name": "allocation_error_signed",
            "mode": 2,
            "handle": 0xFFFF,
            "free_bytes": 0x80000000,
        },
        {"name": "unknown_mode", "mode": 7},
    )
    data_file_offset = 0xD420
    literal_offsets = (0x002E, 0x0041, 0x0055, 0x0073, 0x007D)
    literals = {}
    for offset in literal_offsets:
        end = EXE.index(0, data_file_offset + offset)
        literals[offset] = EXE[data_file_offset + offset : end]
    if literals != {
        0x002E: b"ERREUR DE CODAGE !",
        0x0041: b"ERREUR DE FICHIER :",
        0x0055: b"ERREUR D'ALLOCATION MEMOIRE !",
        0x0073: b"HANDLE : ",
        0x007D: b"LIBRE  : ",
    }:
        raise AssertionError("0x0d75: error-overlay literals changed")

    game_segment = 0x3000
    detail_segment = 0x4000
    resource_segment = 0x5000
    caller_es_segment = 0x7100
    stack_segment = 0x9000
    detail_offset = 0x0220
    number_offset = 0x0AF2
    caller_sp = 0xFF00
    stack_sentinel = bytes.fromhex("5aa5966987783cc3")
    helper_targets = {
        0x02065: "bloodprg_strlen",
        0x00E62: "layout_offset_calc",
        0x030EA: "small_text_render",
        0x01EB2: "decimal_append_i16",
        0x01EEB: "decimal_append_i32",
    }
    vectors = []

    def signed16(value: int) -> int:
        return value - 0x10000 if value & 0x8000 else value

    def signed32(value: int) -> int:
        return value - 0x100000000 if value & 0x80000000 else value

    def c_string(machine: Uc, segment: int, offset: int) -> str:
        raw = bytes(machine.mem_read(segment * 16 + offset, 128))
        return raw.split(b"\0", 1)[0].decode("ascii")

    for case_index, case in enumerate(cases):
        name = str(case["name"])
        mode = int(case["mode"])
        detail = bytes(case.get("detail", b"unused"))
        handle = int(case.get("handle", 0xA55A))
        free_bytes = int(case.get("free_bytes", 0x89ABCDEF))
        layout_x = 0x0040 + case_index * 7
        layout_y = 0x0030 + case_index * 5

        game_before = bytearray(
            (offset * 31 + (offset >> 8) * 17 + case_index * 23 + 0x39)
            & 0xFF
            for offset in range(0x10000)
        )
        for offset, literal in literals.items():
            game_before[offset : offset + len(literal) + 1] = literal + b"\0"
        struct.pack_into("<HH", game_before, 0x5221, 0x2468, 0x5678)
        struct.pack_into("<I", game_before, 0x0A46, free_bytes)
        detail_before = bytearray(
            (offset * 13 + case_index * 19 + 0x57) & 0xFF
            for offset in range(0x10000)
        )
        detail_before[detail_offset : detail_offset + len(detail) + 1] = (
            detail + b"\0"
        )
        resource_before = bytearray(
            (offset * 29 + case_index * 11 + 0x73) & 0xFF
            for offset in range(0x10000)
        )
        struct.pack_into("<H", resource_before, 0x0C00, handle)
        expected_game = bytearray(game_before)
        expected_calls: list[dict[str, object]] = []

        def expected_call(
            callee: str, return_ip: int, **arguments: object
        ) -> None:
            expected_calls.append(
                {
                    "callee": callee,
                    "return": [return_ip, 0],
                    "display_segment": 0xA000,
                    **arguments,
                }
            )

        if mode == 0:
            expected_call(
                "bloodprg_strlen",
                0x0D9E,
                pointer=[game_segment, 0x002E],
                text=literals[0x002E].decode("ascii"),
            )
            expected_call(
                "layout_offset_calc",
                0x0DA5,
                columns=len(literals[0x002E]),
                rows=1,
            )
            expected_call(
                "small_text_render",
                0x0DAD,
                pointer=[game_segment, 0x002E],
                text=literals[0x002E].decode("ascii"),
                x=layout_x,
                y=layout_y,
                color=15,
            )
        elif mode == 1:
            expected_call(
                "bloodprg_strlen",
                0x0DC7,
                pointer=[game_segment, 0x0041],
                text=literals[0x0041].decode("ascii"),
            )
            expected_call(
                "layout_offset_calc",
                0x0DCE,
                columns=len(literals[0x0041]),
                rows=2,
            )
            expected_call(
                "small_text_render",
                0x0DD6,
                pointer=[game_segment, 0x0041],
                text=literals[0x0041].decode("ascii"),
                x=layout_x,
                y=layout_y,
                color=15,
            )
            expected_call(
                "small_text_render",
                0x0DE0,
                pointer=[detail_segment, detail_offset],
                text=detail.decode("ascii"),
                x=layout_x,
                y=(layout_y + 6) & 0xFFFF,
                color=15,
            )
        elif mode == 2:
            handle_text = str(signed16(handle))
            free_text = str(signed32(free_bytes))
            expected_call(
                "bloodprg_strlen",
                0x0DF7,
                pointer=[game_segment, 0x0055],
                text=literals[0x0055].decode("ascii"),
            )
            expected_call(
                "layout_offset_calc",
                0x0DFE,
                columns=len(literals[0x0055]),
                rows=3,
            )
            expected_call(
                "small_text_render",
                0x0E06,
                pointer=[game_segment, 0x0055],
                text=literals[0x0055].decode("ascii"),
                x=layout_x,
                y=layout_y,
                color=15,
            )
            expected_call(
                "small_text_render",
                0x0E11,
                pointer=[game_segment, 0x0073],
                text=literals[0x0073].decode("ascii"),
                x=layout_x,
                y=(layout_y + 6) & 0xFFFF,
                color=15,
            )
            expected_call(
                "bloodprg_strlen",
                0x0E1A,
                pointer=[game_segment, 0x0073],
                text=literals[0x0073].decode("ascii"),
            )
            expected_call(
                "decimal_append_i16",
                0x0E2C,
                value=signed16(handle),
                destination=[game_segment, number_offset],
                text=handle_text,
            )
            expected_game[
                number_offset : number_offset + len(handle_text) + 1
            ] = handle_text.encode("ascii") + b"\0"
            expected_call(
                "small_text_render",
                0x0E34,
                pointer=[game_segment, number_offset],
                text=handle_text,
                x=(layout_x + len(literals[0x0073]) * 4) & 0xFFFF,
                y=(layout_y + 6) & 0xFFFF,
                color=15,
            )
            expected_call(
                "small_text_render",
                0x0E40,
                pointer=[game_segment, 0x007D],
                text=literals[0x007D].decode("ascii"),
                x=layout_x,
                y=(layout_y + 12) & 0xFFFF,
                color=15,
            )
            expected_call(
                "decimal_append_i32",
                0x0E4A,
                value=signed32(free_bytes),
                destination=[game_segment, number_offset],
                text=free_text,
            )
            expected_game[
                number_offset : number_offset + len(free_text) + 1
            ] = free_text.encode("ascii") + b"\0"
            expected_call(
                "small_text_render",
                0x0E53,
                pointer=[game_segment, number_offset],
                text=free_text,
                x=(layout_x + len(literals[0x0073]) * 4) & 0xFFFF,
                y=(layout_y + 12) & 0xFFFF,
                color=15,
            )

        initial = {
            "eax": 0xA5A50000 | mode,
            "ebx": 0xB6B62345 + case_index,
            "ecx": 0xC7C73456 + case_index,
            "edx": 0xD8D80000 | detail_offset,
            "esi": 0xE9E95678 + case_index,
            "edi": 0xFAFA6789 + case_index,
            "ebp": 0xABCD789A + case_index,
            "sp": caller_sp,
            "ds": detail_segment,
            "es": caller_es_segment,
            "fs": resource_segment,
            "gs": game_segment,
            "ss": stack_segment,
            "flags": 0x0202,
        }
        calls: list[dict[str, object]] = []

        def stack_word(machine: Uc, index: int = 0) -> int:
            stack_pointer = machine.reg_read(UC_X86_REG_SP)
            return struct.unpack(
                "<H",
                machine.mem_read(
                    stack_segment * 16 + stack_pointer + index * 2, 2
                ),
            )[0]

        def capture(machine: Uc, address: int, _size: int) -> None:
            callee = helper_targets.get(address)
            if callee is None:
                return
            display_segment = struct.unpack(
                "<H", machine.mem_read(game_segment * 16 + 0x5223, 2)
            )[0]
            call: dict[str, object] = {
                "callee": callee,
                "return": [stack_word(machine), stack_word(machine, 1)],
                "display_segment": display_segment,
            }
            if callee == "bloodprg_strlen":
                segment = machine.reg_read(UC_X86_REG_ES)
                offset = machine.reg_read(UC_X86_REG_DI)
                text_value = c_string(machine, segment, offset)
                call["pointer"] = [segment, offset]
                call["text"] = text_value
                machine.reg_write(UC_X86_REG_AX, len(text_value))
            elif callee == "layout_offset_calc":
                call["columns"] = machine.reg_read(UC_X86_REG_AX)
                call["rows"] = machine.reg_read(UC_X86_REG_BX)
                machine.reg_write(UC_X86_REG_AX, layout_x)
                machine.reg_write(UC_X86_REG_BX, layout_y)
            elif callee == "small_text_render":
                segment = machine.reg_read(UC_X86_REG_DS)
                offset = machine.reg_read(UC_X86_REG_SI)
                call["pointer"] = [segment, offset]
                call["text"] = c_string(machine, segment, offset)
                call["x"] = machine.reg_read(UC_X86_REG_AX)
                call["y"] = machine.reg_read(UC_X86_REG_BX)
                call["color"] = machine.reg_read(UC_X86_REG_DX)
            elif callee == "decimal_append_i16":
                value = signed16(machine.reg_read(UC_X86_REG_AX))
                segment = machine.reg_read(UC_X86_REG_ES)
                offset = machine.reg_read(UC_X86_REG_DI)
                text_value = str(value)
                call["value"] = value
                call["destination"] = [segment, offset]
                call["text"] = text_value
                machine.mem_write(
                    segment * 16 + offset, text_value.encode("ascii") + b"\0"
                )
            else:
                value = signed32(machine.reg_read(UC_X86_REG_EAX))
                segment = machine.reg_read(UC_X86_REG_ES)
                offset = machine.reg_read(UC_X86_REG_DI)
                text_value = str(value)
                call["value"] = value
                call["destination"] = [segment, offset]
                call["text"] = text_value
                machine.mem_write(
                    segment * 16 + offset, text_value.encode("ascii") + b"\0"
                )
            calls.append(call)

        machine = execute(
            entry,
            return_address,
            initial,
            [
                (0, return_address, b"\xCC"),
                *[
                    (address >> 4, address & 0xF, b"\xCB")
                    for address in helper_targets
                ],
                (game_segment, 0, bytes(game_before)),
                (detail_segment, 0, bytes(detail_before)),
                (resource_segment, 0, bytes(resource_before)),
                (
                    stack_segment,
                    caller_sp,
                    struct.pack("<HH", return_address, 0) + stack_sentinel,
                ),
            ],
            code_handler=capture,
            instruction_count=1000,
        )

        if calls != expected_calls:
            raise AssertionError(
                f"0x0d75 {name}: calls={calls!r}, expected={expected_calls!r}"
            )
        actual_game = bytes(machine.mem_read(game_segment * 16, 0x10000))
        if actual_game != bytes(expected_game):
            mismatch = next(
                offset
                for offset, (actual, expected) in enumerate(
                    zip(actual_game, expected_game)
                )
                if actual != expected
            )
            raise AssertionError(
                f"0x0d75 {name}: game mismatch at {mismatch:#06x}"
            )
        if bytes(machine.mem_read(detail_segment * 16, 0x10000)) != bytes(
            detail_before
        ):
            raise AssertionError(f"0x0d75 {name}: detail memory changed")
        if bytes(machine.mem_read(resource_segment * 16, 0x10000)) != bytes(
            resource_before
        ):
            raise AssertionError(f"0x0d75 {name}: resource memory changed")

        expected_registers = dict(initial)
        del expected_registers["flags"]
        expected_registers["sp"] = caller_sp + 4
        for register, expected_value in expected_registers.items():
            actual_value = machine.reg_read(REGISTERS[register])
            if actual_value != expected_value:
                raise AssertionError(
                    f"0x0d75 {name}: {register}={actual_value:#x}, "
                    f"expected={expected_value:#x}"
                )
        if bytes(
            machine.mem_read(stack_segment * 16 + caller_sp + 4, len(stack_sentinel))
        ) != stack_sentinel:
            raise AssertionError(f"0x0d75 {name}: caller stack changed")

        vectors.append(
            {
                "name": name,
                "mode": mode,
                "detail": detail.decode("ascii"),
                "resource_handle_signed": signed16(handle),
                "resource_free_bytes_signed": signed32(free_bytes),
                "layout_result": [layout_x, layout_y] if mode <= 2 else None,
                "calls": calls,
                "display_pointer_after": list(
                    struct.unpack_from("<HH", actual_game, 0x5221)
                ),
                "number_buffer_after": (
                    c_string(machine, game_segment, number_offset)
                    if mode == 2
                    else None
                ),
                "preserved_registers": [
                    "eax",
                    "ebx",
                    "ecx",
                    "edx",
                    "esi",
                    "edi",
                    "ebp",
                    "ds",
                    "es",
                    "fs",
                    "gs",
                    "ss",
                ],
                "return": "far",
            }
        )

    return vectors


def ui_region_31_poll_vectors() -> list[dict[str, object]]:
    entry = 0x82C3
    return_address = 0xFC23
    expected_hash = "ed06b04960c68f21312006c2f4dfbf201f6e6200e202d110e8cad963d288bbff"
    if hashlib.sha256(EXE[entry : entry + 37]).hexdigest() != expected_hash:
        raise AssertionError("0x82c3: recovered 37-byte body changed")

    cases = (
        {
            "name": "disabled_for_all_attempts",
            "flags": 0xA5FE,
            "rect": (-20, -10, 40, 20),
            "mouse": (0, 0),
            "primary": 1,
            "expected": -1,
            "expected_calls": 0,
            "expected_iterations": 32,
        },
        {
            "name": "immediate_signed_hit",
            "flags": 0xA501,
            "rect": (-120, 100, 40, 30),
            "mouse": (-100, 123),
            "primary": 1,
            "expected": 31,
            "expected_calls": 1,
            "expected_iterations": 1,
        },
        {
            "name": "same_region_misses_32_times",
            "flags": 0x0001,
            "rect": (100, 100, 5, 5),
            "mouse": (0, 0),
            "primary": 1,
            "expected": -1,
            "expected_calls": 32,
            "expected_iterations": 32,
        },
        {
            "name": "mouse_enabled_on_third_call",
            "flags": 0x7F01,
            "rect": (-10, -10, 20, 20),
            "mouse": (0, 0),
            "primary": 0,
            "primary_on_call": 3,
            "expected": 29,
            "expected_calls": 3,
            "expected_iterations": 3,
        },
        {
            "name": "region_enabled_on_fifth_iteration",
            "flags": 0x55FE,
            "rect": (-20, -20, 40, 40),
            "mouse": (0, 0),
            "primary": 1,
            "flags_on_iteration": 5,
            "expected": 27,
            "expected_calls": 1,
            "expected_iterations": 5,
        },
        {
            "name": "mouse_gate_blocks_all_calls",
            "flags": 0x0001,
            "rect": (-1, -1, 2, 2),
            "mouse": (0, 0),
            "primary": 0,
            "expected": -1,
            "expected_calls": 32,
            "expected_iterations": 32,
        },
    )
    game_segment = 0x6400
    decoy_segment = 0x8000
    caller_sp = 0xFF00
    stack_sentinel = bytes.fromhex("87a55a963cc37869")
    table_offset = 0x6212
    record_size = 0x20
    vectors = []

    def signed_word(value: int) -> int:
        return value & 0xFFFF

    for case_index, case in enumerate(cases):
        name = str(case["name"])
        mouse_x, mouse_y = (int(value) for value in case["mouse"])
        primary = int(case["primary"])
        flags = int(case["flags"])
        rect = tuple(int(value) for value in case["rect"])
        expected = int(case["expected"])
        expected_calls = int(case["expected_calls"])
        expected_iterations = int(case["expected_iterations"])
        primary_on_call = int(case.get("primary_on_call", 0))
        flags_on_iteration = int(case.get("flags_on_iteration", 0))

        game_before = bytearray(
            (offset * 29 + (offset >> 8) * 13 + case_index * 17 + 0x4D)
            & 0xFF
            for offset in range(0x10000)
        )
        for region_id in range(32):
            record_offset = table_offset + region_id * record_size
            game_before[record_offset : record_offset + record_size] = bytes(
                (region_id * 19 + byte_index * 23 + case_index * 11) & 0xFF
                for byte_index in range(record_size)
            )
            struct.pack_into("<H", game_before, record_offset, 0xA5FE)
        record_offset = table_offset + 31 * record_size
        rect_offset = record_offset + 8
        struct.pack_into("<H", game_before, record_offset, flags & 0xFFFF)
        struct.pack_into(
            "<HHHH",
            game_before,
            rect_offset,
            *(signed_word(value) for value in rect),
        )
        struct.pack_into("<H", game_before, 0x0A2A, signed_word(mouse_x))
        struct.pack_into("<H", game_before, 0x0A2C, signed_word(mouse_y))
        game_before[0x0A3E] = primary
        game_before[caller_sp : caller_sp + 4 + len(stack_sentinel)] = (
            struct.pack("<HH", return_address, 0) + stack_sentinel
        )
        decoy_before = bytes(
            (offset * 7 + case_index * 31 + 0xB3) & 0xFF
            for offset in range(0x10000)
        )

        initial = {
            "eax": 0xA5A51234,
            "ebx": 0xB6B62345,
            "ecx": 0xC7C73456,
            "edx": 0xD8D84567,
            "esi": 0xE9E95678,
            "edi": 0xFAFA6789,
            "ebp": 0xABCD789A,
            "sp": caller_sp,
            "ds": game_segment,
            "es": 0x5100,
            "fs": 0x5300,
            "gs": decoy_segment,
            "ss": game_segment,
            "flags": 0x0202,
        }
        calls: list[dict[str, object]] = []
        iterations = 0

        def capture(machine: Uc, address: int, _size: int) -> None:
            nonlocal iterations
            if address == 0x82C8:
                iterations += 1
                if flags_on_iteration == iterations:
                    machine.mem_write(
                        game_segment * 16 + record_offset,
                        struct.pack("<H", flags | 1),
                    )
                return
            if address != 0x8295:
                return
            call_number = len(calls) + 1
            if primary_on_call == call_number:
                machine.mem_write(game_segment * 16 + 0x0A3E, b"\x01")
            actual_rect_offset = machine.reg_read(UC_X86_REG_BP)
            actual_rect = struct.unpack(
                "<hhhh",
                machine.mem_read(game_segment * 16 + actual_rect_offset, 8),
            )
            calls.append(
                {
                    "attempts_remaining": machine.reg_read(UC_X86_REG_AX),
                    "rect_offset": actual_rect_offset,
                    "rect": list(actual_rect),
                }
            )

        machine = execute(
            entry,
            return_address,
            initial,
            [
                (game_segment, 0, bytes(game_before)),
                (decoy_segment, 0, decoy_before),
            ],
            code_handler=capture,
            instruction_count=1000,
        )

        if len(calls) != expected_calls:
            raise AssertionError(
                f"0x82c3 {name}: calls={len(calls)}, expected={expected_calls}"
            )
        if iterations != expected_iterations:
            raise AssertionError(
                f"0x82c3 {name}: iterations={iterations}, "
                f"expected={expected_iterations}"
            )
        if any(int(call["rect_offset"]) != rect_offset for call in calls):
            raise AssertionError(f"0x82c3 {name}: rectangle pointer advanced")
        expected_call_start = (
            32 - flags_on_iteration if flags_on_iteration else 31
        )
        expected_attempt_values = list(
            range(expected_call_start, expected_call_start - expected_calls, -1)
        )
        actual_attempt_values = [
            int(call["attempts_remaining"]) for call in calls
        ]
        if actual_attempt_values != expected_attempt_values:
            raise AssertionError(
                f"0x82c3 {name}: attempts={actual_attempt_values}, "
                f"expected={expected_attempt_values}"
            )
        actual_result = machine.reg_read(UC_X86_REG_AX)
        expected_result = expected & 0xFFFF
        if actual_result != expected_result:
            raise AssertionError(
                f"0x82c3 {name}: ax={actual_result:#x}, "
                f"expected={expected_result:#x}"
            )
        expected_registers = dict(initial)
        del expected_registers["flags"]
        expected_registers["eax"] = (
            initial["eax"] & 0xFFFF0000
        ) | expected_result
        expected_registers["sp"] = caller_sp + 4
        for register, expected_value in expected_registers.items():
            actual_value = machine.reg_read(REGISTERS[register])
            if actual_value != expected_value:
                raise AssertionError(
                    f"0x82c3 {name}: {register}={actual_value:#x}, "
                    f"expected={expected_value:#x}"
                )
        carry = bool(machine.reg_read(UC_X86_REG_EFLAGS) & 1)
        if carry != (expected >= 0):
            raise AssertionError(f"0x82c3 {name}: carry={carry}")
        expected_game = bytearray(game_before)
        if primary_on_call:
            expected_game[0x0A3E] = 1
        if flags_on_iteration:
            struct.pack_into("<H", expected_game, record_offset, flags | 1)
        actual_game = bytes(machine.mem_read(game_segment * 16, 0x10000))
        if (
            actual_game[:0xFE00] != bytes(expected_game[:0xFE00])
            or actual_game[caller_sp + 4 :] != bytes(expected_game[caller_sp + 4 :])
        ):
            raise AssertionError(f"0x82c3 {name}: non-stack game memory changed")
        if bytes(machine.mem_read(decoy_segment * 16, 0x10000)) != decoy_before:
            raise AssertionError(f"0x82c3 {name}: GS decoy memory changed")
        if bytes(
            machine.mem_read(
                game_segment * 16 + caller_sp + 4, len(stack_sentinel)
            )
        ) != stack_sentinel:
            raise AssertionError(f"0x82c3 {name}: caller stack changed")

        vectors.append(
            {
                "name": name,
                "mouse": [mouse_x, mouse_y],
                "primary": primary,
                "initial_flags": flags,
                "rect": list(rect),
                "flags_on_iteration": flags_on_iteration or None,
                "primary_on_call": primary_on_call or None,
                "result": expected,
                "iterations": iterations,
                "calls": calls,
                "carry": carry,
                "table_sha256": hashlib.sha256(
                    game_before[table_offset : table_offset + 32 * record_size]
                ).hexdigest(),
                "return": "far",
            }
        )

    return vectors


def ship_3d_navigation_candidate_build_vectors() -> list[dict[str, object]]:
    entry = 0x70EE
    return_address = 0xF0EE
    expected_hash = "900f4f7fa776f880c818e637a2d67d768aafbc885b5f9f9f021956cec82f6bf7"
    if hashlib.sha256(EXE[entry : entry + 79]).hexdigest() != expected_hash:
        raise AssertionError("0x70ee: recovered 79-byte body changed")

    cases = (
        {
            "name": "empty_source",
            "source": [],
            "honk": 0x7777,
            "record_base": 0x0200,
            "objects": {},
            "expected": [],
        },
        {
            "name": "two_active_kind_two",
            "source": [0x0010, 0x0030],
            "honk": 0x7777,
            "record_base": 0x0100,
            "objects": {
                0x0010: (2, 0x01),
                0x0030: (2, 0xA5),
            },
            "expected": [0x0010, 0x0030],
        },
        {
            "name": "exclude_honk_before_record_read",
            "source": [0x0020, 0x0040],
            "honk": 0x0020,
            "record_base": 0x0300,
            "objects": {
                0x0020: (2, 0x01),
                0x0040: (2, 0x01),
            },
            "expected": [0x0040],
        },
        {
            "name": "mixed_kind_and_activity",
            "source": [0x0004, 0x0010, 0x0020, 0x0030, 0x0040],
            "honk": 0x8888,
            "record_base": 0x0123,
            "objects": {
                0x0004: (1, 0x01),
                0x0010: (2, 0x00),
                0x0020: (0x0102, 0x01),
                0x0030: (2, 0x80),
                0x0040: (2, 0x81),
            },
            "expected": [0x0040],
        },
        {
            "name": "zero_offset_is_valid",
            "source": [0x0000, 0x0006],
            "honk": 0x9999,
            "record_base": 0x0400,
            "objects": {
                0x0000: (2, 0x01),
                0x0006: (2, 0x01),
            },
            "expected": [0x0000, 0x0006],
        },
        {
            "name": "unsigned_high_offsets",
            "source": [0x8000, 0xFFFE],
            "honk": 0x7777,
            "record_base": 0x0000,
            "objects": {
                0x8000: (2, 0x01),
                0xFFFE: (2, 0x01),
            },
            "expected": [0x8000, 0xFFFE],
        },
        {
            "name": "all_rejected",
            "source": [0x0010, 0x0020, 0x0030],
            "honk": 0x0010,
            "record_base": 0x0550,
            "objects": {
                0x0020: (3, 0x01),
                0x0030: (2, 0xFE),
            },
            "expected": [],
        },
    )
    game_segment = 0x6000
    decoy_segment = 0x5000
    record_segment = 0xA000
    target_segment = 0x9000
    target_offset = 0x2468
    source_offset = 0x6886
    destination_offset = 0x2B53
    caller_sp = 0xFF00
    stack_sentinel = bytes.fromhex("3ca5875a966978c3")
    vectors = []

    for case_index, case in enumerate(cases):
        name = str(case["name"])
        source = [int(value) for value in case["source"]]
        honk = int(case["honk"])
        record_base = int(case["record_base"])
        objects = {
            int(object_offset): tuple(int(value) for value in values)
            for object_offset, values in dict(case["objects"]).items()
        }
        expected = [int(value) for value in case["expected"]]

        game_before = bytearray(
            (offset * 19 + (offset >> 8) * 31 + case_index * 23 + 0x35)
            & 0xFF
            for offset in range(0x10000)
        )
        struct.pack_into(
            "<HH", game_before, 0x6724, record_base, record_segment
        )
        struct.pack_into("<H", game_before, 0x6754, honk)
        for index in range(16):
            struct.pack_into(
                "<H", game_before, source_offset + index * 2, 0xD000 + index
            )
            struct.pack_into(
                "<H", game_before, destination_offset + index * 2, 0xE000 + index
            )
        game_before[caller_sp : caller_sp + 4 + len(stack_sentinel)] = (
            struct.pack("<HH", return_address, 0) + stack_sentinel
        )
        expected_game = bytearray(game_before)
        source_words = source + [0xFFFF]
        for index, value in enumerate(source_words):
            struct.pack_into(
                "<H", expected_game, source_offset + index * 2, value
            )
        for index, value in enumerate(expected + [0]):
            struct.pack_into(
                "<H", expected_game, destination_offset + index * 2, value
            )

        record_before = bytearray(
            (offset * 7 + (offset >> 8) * 13 + case_index * 29 + 0x59)
            & 0xFF
            for offset in range(0x20020)
        )
        for object_offset, (kind, flags) in objects.items():
            object_address = record_base + object_offset
            struct.pack_into("<H", record_before, object_address, kind)
            record_before[object_address + 2] = flags
        decoy_before = bytes(
            (offset * 11 + case_index * 17 + 0xA7) & 0xFF
            for offset in range(0x10000)
        )

        initial = {
            "eax": 0xA5A51234,
            "ebx": 0xB6B62345,
            "ecx": 0xC7C73456,
            "edx": 0xD8D84567,
            "esi": 0xE9E95678,
            "edi": target_offset,
            "ebp": 0xABCD789A,
            "sp": caller_sp,
            "ds": decoy_segment,
            "es": target_segment,
            "fs": 0x7000,
            "gs": game_segment,
            "ss": game_segment,
            "flags": 0x0202,
        }
        helper_calls: list[dict[str, object]] = []

        def capture(machine: Uc, address: int, _size: int) -> None:
            if address != 0x624B:
                return
            stack_pointer = machine.reg_read(UC_X86_REG_SP)
            helper_calls.append(
                {
                    "eax": machine.reg_read(UC_X86_REG_EAX),
                    "bp": machine.reg_read(UC_X86_REG_BP),
                    "target": [
                        machine.reg_read(UC_X86_REG_ES),
                        machine.reg_read(UC_X86_REG_DI),
                    ],
                    "ds": machine.reg_read(UC_X86_REG_DS),
                    "return": list(
                        struct.unpack(
                            "<HH",
                            machine.mem_read(
                                game_segment * 16 + stack_pointer, 4
                            ),
                        )
                    ),
                }
            )
            for index, value in enumerate(source_words):
                machine.mem_write(
                    game_segment * 16 + source_offset + index * 2,
                    struct.pack("<H", value),
                )
            machine.reg_write(
                UC_X86_REG_BP, (source_offset + (len(source_words) - 1) * 2) & 0xFFFF
            )

        machine = execute(
            entry,
            return_address,
            initial,
            [
                (0, 0x624B, b"\xCB"),
                (game_segment, 0, bytes(game_before)),
                (decoy_segment, 0, decoy_before),
                (record_segment, 0, bytes(record_before)),
            ],
            code_handler=capture,
            instruction_count=1000,
        )

        expected_helper_calls = [
            {
                "eax": 0,
                "bp": source_offset,
                "target": [target_segment, target_offset],
                "ds": decoy_segment,
                "return": [0x70FD, 0],
            }
        ]
        if helper_calls != expected_helper_calls:
            raise AssertionError(
                f"0x70ee {name}: helper={helper_calls!r}, "
                f"expected={expected_helper_calls!r}"
            )
        actual_game = bytes(machine.mem_read(game_segment * 16, 0x10000))
        if (
            actual_game[:0xFE00] != bytes(expected_game[:0xFE00])
            or actual_game[caller_sp + 4 :] != bytes(expected_game[caller_sp + 4 :])
        ):
            mismatch = next(
                offset
                for offset, (actual, expected_byte) in enumerate(
                    zip(actual_game[:0xFE00], expected_game[:0xFE00])
                )
                if actual != expected_byte
            )
            raise AssertionError(
                f"0x70ee {name}: game mismatch at {mismatch:#06x}"
            )
        if bytes(
            machine.mem_read(record_segment * 16, len(record_before))
        ) != bytes(record_before):
            raise AssertionError(f"0x70ee {name}: record memory changed")
        if bytes(machine.mem_read(decoy_segment * 16, 0x10000)) != decoy_before:
            raise AssertionError(f"0x70ee {name}: DS decoy memory changed")

        last_kind = initial["ebx"] & 0xFFFF
        for object_offset in source:
            if object_offset != honk:
                last_kind = objects[object_offset][0] & 0xFFFF
        expected_registers = dict(initial)
        del expected_registers["flags"]
        expected_registers["ebx"] = (
            initial["ebx"] & 0xFFFF0000
        ) | last_kind
        expected_registers["edi"] = (
            initial["edi"] & 0xFFFF0000
        ) | record_base
        expected_registers["es"] = record_segment
        expected_registers["sp"] = caller_sp + 4
        for register, expected_value in expected_registers.items():
            actual_value = machine.reg_read(REGISTERS[register])
            if actual_value != expected_value:
                raise AssertionError(
                    f"0x70ee {name}: {register}={actual_value:#x}, "
                    f"expected={expected_value:#x}"
                )
        expected_flags = (initial["flags"] & ~0x08D5) | 0x0044
        actual_flags = machine.reg_read(UC_X86_REG_EFLAGS)
        if (actual_flags & 0x0ED7) != (expected_flags & 0x0ED7):
            raise AssertionError(
                f"0x70ee {name}: flags={actual_flags:#x}, "
                f"expected={expected_flags:#x}"
            )
        if bytes(
            machine.mem_read(
                game_segment * 16 + caller_sp + 4, len(stack_sentinel)
            )
        ) != stack_sentinel:
            raise AssertionError(f"0x70ee {name}: caller stack changed")

        vectors.append(
            {
                "name": name,
                "source": source,
                "honk": honk,
                "record_base": [record_segment, record_base],
                "objects": {
                    f"{object_offset:#06x}": [kind, flags]
                    for object_offset, (kind, flags) in objects.items()
                },
                "output": expected,
                "helper": helper_calls[0],
                "final_bx": last_kind,
                "return": "far",
            }
        )

    return vectors


